'use strict';
(() => {
 const KEY='network-final-01076040-v1', SESSION=KEY+'-session';
 const icons={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',book:'M12 5v16M12 5C8 2 4 3 2 4v15c3-1 6-1 10 2 4-3 7-3 10-2V4c-3-1-6-1-10 1Z',quiz:'M7 3h10a2 2 0 0 1 2 2v16H5V5a2 2 0 0 1 2-2Zm1 5h8m-8 4h8m-8 4h5',review:'M3 11a9 9 0 1 1 2 7M3 5v6h6m3-5v6l4 2',search:'M21 21l-5-5m2-6a7 7 0 1 1-14 0 7 7 0 0 1 14 0',arrow:'M5 12h14m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',info:'M12 11v6m0-10v1m9 4a9 9 0 1 1-18 0 9 9 0 0 1 18 0',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',play:'m8 4 12 8-12 8V4Z',left:'M19 12H5m6-6-6 6 6 6',copy:'M8 8h12v13H8V8ZM4 16H2V2h12v2',flag:'M5 22V3m0 1c5-4 9 4 15 0v10c-6 4-10-4-15 0',grad:'m2 8 10-5 10 5-10 5L2 8Zm4 2v7c4 3 8 3 12 0v-7m4-2v9'};
 const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=s=>esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
 let storageOK=true, state={done:[],answers:{},history:[]}, session=null, reviewFilter='all';
 try{const old=JSON.parse(localStorage.getItem(KEY));if(old&&Array.isArray(old.done)&&old.answers&&Array.isArray(old.history))state=old;session=JSON.parse(sessionStorage.getItem(SESSION));}catch(e){storageOK=false;}
 const chapters=window.CHAPTERS;
 if(!Array.isArray(chapters)||chapters.length!==8){document.getElementById('main').innerHTML='<div class="empty-state"><h1>โหลดบทเรียนไม่สำเร็จ</h1><p>กรุณารีเฟรชหน้าเว็บอีกครั้ง</p></div>';return;}
 const allQuestions=chapters.flatMap(c=>c.questions.map(q=>({...q,chapterId:c.id,chapterTitle:c.shortTitle})));
 const qmap=Object.fromEntries(allQuestions.map(q=>[q.id,q]));
 if(session&&(!Array.isArray(session.ids)||session.ids.some(id=>!qmap[id])))session=null;
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;}};
 const saveSession=()=>{try{sessionStorage.setItem(SESSION,JSON.stringify(session));}catch(e){}};
 const wrongIds=()=>Object.keys(state.answers).filter(id=>qmap[id]&&!state.answers[id].correct);
 const main=document.getElementById('main');
 const toast=text=>{const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2600)};
 const logo=`<svg width="40" height="44" viewBox="0 0 44 44" fill="none" stroke="currentColor" stroke-width="3.5" aria-hidden="true"><path d="m22 7-16 30h32L22 7Z"/><circle cx="22" cy="7" r="5" fill="white"/><circle cx="6" cy="37" r="5" fill="white"/><circle cx="38" cy="37" r="5" fill="white"/></svg>`;
 function sidebar(active='home',cid){document.getElementById('sidebar').innerHTML=`<a href="#/" class="brand">${logo}<span><strong>Network</strong><small>FINAL LAB</small></span></a><nav aria-label="ส่วนหลัก">${[['home','ภาพรวม','#/'],['book','บทเรียน','#/chapters'],['quiz','ข้อสอบฝึก','#/practice'],['review','ทบทวนจุดที่พลาด','#/review']].map(([key,title,url])=>`<a class="nav-item ${key===active?'active':''}" href="${url}" ${key===active?'aria-current="page"':''}>${icon(key)}${title}${key==='review'&&wrongIds().length?` <small>(${wrongIds().length})</small>`:''}</a>`).join('')}</nav><hr class="nav-divider"><p class="nav-label">8 บทเรียน · FINAL EXAM</p><nav aria-label="รายการบทเรียน">${chapters.map(c=>`<a class="nav-item chapter-nav ${cid===c.id?'active':''}" href="#/chapter/${c.id}" ${cid===c.id?'aria-current="page"':''}><span class="chapter-num ${state.done.includes(c.id)?'done':''}">${state.done.includes(c.id)?icon('check',14):c.id}</span>${esc(c.shortTitle)}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="exam-scope.pdf" target="_blank" rel="noopener">${icon('download',16)}แนวข้อสอบอาจารย์ (PDF)</a><span>${icon('grad',16)} รายวิชา 01076040</span></div>`;}
 function breadcrumb(label='ภาพรวม'){document.getElementById('breadcrumb').innerHTML=`<a href="#/"><b>Network</b></a><span>/</span><span class="crumb-detail">${esc(label)}</span>`;document.title=`${label} · Network Final Lab`;}
 function chapterCard(c){return `<a href="#/chapter/${c.id}" class="chapter-card"><span class="num">${state.done.includes(c.id)?icon('check',20):String(c.id).padStart(2,'0')}</span><div class="detail"><h3>${esc(c.shortTitle)}</h3><p>${esc(c.subtitle)}</p></div><span class="count">15 ข้อ</span>${icon('arrow',18)}</a>`}
 function scopeNote(){return `<details class="scope-note"><summary>ขอบเขตและที่มาของเนื้อหา</summary><p>ยึดไฟล์ “แนวเนื้อหาข้อสอบปลายภาค_Network.pdf” ทั้ง 5 หน้าเป็นขอบเขตหลัก แบ่งตามหัวข้อ 1–8 และเสริมตัวอย่างจากเรื่อง Switching/MAC, VLAN/VTP, VRRP/HSRP และ Lab OSPF ที่เคยทบทวน</p><ul><li>ข้อสอบฝึก 120 ข้อในเว็บนี้สร้างขึ้นเพื่อทบทวน ไม่ใช่ข้อสอบจริงหรือข้อสอบที่อาจารย์รับรอง</li><li>WLAN อยู่ในคำอธิบายรายวิชา แต่ไม่ได้แยกเป็นหัวข้อในแนวปลายภาคฉบับนี้ จึงเน้น 8 บทตามไฟล์ ส่วน IP Telephony ครอบคลุม Voice VLAN ตามแนว</li><li>ตัวอย่างคำสั่งอ้างอิง Cisco IOS ทั่วไป รายละเอียดอาจต่างตามรุ่นและเวอร์ชัน ตรวจชื่อ interface และ IP ให้ตรงกับแลป</li><li>เลขบทกับตำแหน่งใน PDF: บท 1–2 หน้า 1–2, บท 3 หน้า 2–3, บท 4–5 หน้า 3–4, บท 6–7 หน้า 4, บท 8 หน้า 4–5</li></ul><a href="exam-scope.pdf" target="_blank" rel="noopener">เปิดไฟล์แนวข้อสอบต้นฉบับ ${icon('arrow',14)}</a></details>`}
 function dashboard(){sidebar('home');breadcrumb();const answered=Object.keys(state.answers).filter(id=>qmap[id]).length;const percent=Math.round(state.done.length/8*100);const next=chapters.find(c=>!state.done.includes(c.id))||chapters[0];main.innerHTML=`<section class="hero"><div><h1>เชื่อมความเข้าใจ<br>ก่อนเข้าสอบ</h1><p>สรุปและฝึกทำข้อสอบวิชาเครือข่ายครบ 8 บทเรียน<br>พร้อมโจทย์ 120 ข้อ อธิบายตั้งแต่หลักการจนถึงการทำแลป</p><div class="actions"><a class="btn primary" href="#/chapter/${next.id}">${icon('play',17)}${state.done.length?'เรียนบทถัดไป':'เริ่มบทเรียน'}</a><a class="btn" href="#/practice">${icon('quiz',18)}ฝึกทำข้อสอบ</a></div></div><div class="hero-art">${Diagrams.hero()}</div></section><div class="progress-strip"><span>อ่านแล้ว: <strong>${state.done.length} / 8</strong> บท</span><span class="divider"></span><span>ข้อที่เคยทำ: <strong>${answered} / 120</strong></span><div class="progress-track" role="progressbar" aria-label="บทเรียนที่อ่านแล้ว" aria-valuenow="${percent}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${percent}%"></div></div><b>${percent}%</b></div><div class="section-heading"><h2>เส้นทางทบทวน</h2><small>เรียงจากพื้นฐาน → ประยุกต์</small></div><div class="chapter-grid">${chapters.map(chapterCard).join('')}</div><div class="note">${icon('info',21)}<div><strong>เริ่มจาก Switching แล้วเชื่อมต่อไปจนถึง WAN</strong><br>แต่ละบทมีคำอธิบาย แผนภาพ ตัวอย่าง และข้อสอบ 15 ข้อพร้อมเหตุผลของเฉลย</div></div>${scopeNote()}<p class="tiny-note">${storageOK?'ความคืบหน้าบันทึกในเบราว์เซอร์นี้โดยอัตโนมัติ ไม่ซิงก์ข้ามอุปกรณ์':'เบราว์เซอร์ไม่อนุญาตให้บันทึก ความคืบหน้าจะอยู่เฉพาะหน้านี้'}</p>`;}
 function chapterIndex(){sidebar('book');breadcrumb('บทเรียน');main.innerHTML=`<div class="page-head"><div><h1>อ่านให้เข้าใจทีละบท</h1><p class="lead">เรียนรู้ว่าแต่ละส่วนทำงานอย่างไร แล้วเชื่อมโยงเข้ากับสถานการณ์ในแลป</p></div></div><div class="chapter-grid">${chapters.map(chapterCard).join('')}</div>${scopeNote()}`;}
 function sectionHTML(s,i){return `<section class="lesson-section" id="section-${i}"><h2>${esc(s.title)}</h2>${(s.body||[]).map(p=>`<p>${fmt(p)}</p>`).join('')}${s.diagram?Diagrams.render(s.diagram,true):''}${s.bullets?`<ul>${s.bullets.map(b=>`<li>${fmt(b)}</li>`).join('')}</ul>`:''}${s.table?`<div class="table-scroll"><table><thead><tr>${s.table.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${s.table.rows.map(r=>`<tr>${r.map(v=>`<td>${fmt(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}${s.code?`<div class="code-header"><span>ตัวอย่างคำสั่ง / ผลลัพธ์</span><button class="btn small" data-copy="${i}">${icon('copy',13)}คัดลอก</button></div><pre><code>${esc(s.code)}</code></pre>`:''}${s.example?`<div class="example"><h3>${esc(s.example.title)}</h3>${s.example.body.map(p=>`<p>${fmt(p)}</p>`).join('')}</div>`:''}${s.pitfall?`<div class="pitfall"><strong>จุดที่มักสับสน</strong>${fmt(s.pitfall)}</div>`:''}</section>`}
 function lesson(id,summary=false){const c=chapters.find(c=>c.id===id);if(!c){location.hash='#/';return;}sidebar('book',id);breadcrumb(`บท ${id} · ${c.shortTitle}`);main.innerHTML=`<div class="page-head"><div><div class="chapter-label">บท ${String(id).padStart(2,'0')} / 08 · ประมาณ ${c.minutes} นาที</div><h1>${esc(c.title)}</h1><p class="lead">${esc(c.subtitle)}</p></div><button class="btn primary" data-start="${id}">${icon('quiz',17)}ฝึกทำข้อสอบ 15 ข้อ</button></div><div class="tabs" role="tablist" aria-label="รูปแบบบทเรียน"><button class="tab ${!summary?'active':''}" role="tab" aria-selected="${!summary}" data-tab="lesson" data-chapter="${id}">บทเรียน</button><button class="tab ${summary?'active':''}" role="tab" aria-selected="${summary}" data-tab="summary" data-chapter="${id}">สรุปก่อนสอบ</button></div><div class="reading-layout"><article class="reading">${summary?`<h2>จำหลักการให้ได้ แล้วค่อยจำคำสั่ง</h2><ul class="summary-list">${c.summary.map(s=>`<li>${fmt(s)}</li>`).join('')}</ul><div class="note">${icon('info',20)}การอ่านสรุปช่วยทบทวน แต่ถ้ายังอธิบายเหตุผลไม่ได้ ให้กลับไปดูตัวอย่างในบทเรียน</div>`:`<div class="objectives"><strong>อ่านจบแล้ว คุณจะอธิบายได้ว่า…</strong><ul>${c.objectives.map(o=>`<li>${fmt(o)}</li>`).join('')}</ul></div>${c.sections.map(sectionHTML).join('')}`}<div class="chapter-end"><button class="btn ${state.done.includes(id)?'success':'primary'}" data-done="${id}">${icon('check',17)}${state.done.includes(id)?'อ่านบทนี้แล้ว':'ทำเครื่องหมายว่าอ่านแล้ว'}</button>${id<8?`<a class="btn" href="#/chapter/${id+1}">บทถัดไป ${icon('arrow',16)}</a>`:'<a class="btn" href="#/practice">พร้อมฝึกทำข้อสอบ '+icon('arrow',16)+'</a>'}</div><details class="sources"><summary>ที่มาของบทนี้และอ่านเพิ่มเติม</summary><p>ขอบเขตจากแนวข้อสอบอาจารย์ บท ${id}; คำอธิบายและโจทย์เรียบเรียงใหม่เพื่อการเรียนรู้</p><a href="exam-scope.pdf" target="_blank" rel="noopener">แนวข้อสอบต้นฉบับ (PDF 5 หน้า)</a>${c.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`).join('')}</details></article><aside class="toc" aria-label="สารบัญในบท"><h3>เนื้อหาในบทนี้</h3>${summary?'<p class="tiny-note">สรุปแก่นสำคัญทั้งหมดในบท</p>':c.sections.map((s,i)=>`<a href="#/chapter/${id}" data-scroll="section-${i}">${i+1}. ${esc(s.title)}</a>`).join('')}<button class="btn primary" data-start="${id}">${icon('quiz',15)}ฝึกทำข้อสอบ</button><p class="tiny-note">15 ข้อ · พร้อมเฉลยอธิบาย</p></aside></div>`;}
 function practice(){sidebar('quiz');breadcrumb('ข้อสอบฝึก');main.innerHTML=`<div class="page-head"><div><h1>ทดสอบความเข้าใจ</h1><p class="lead">เลือกฝึกพร้อมเฉลยทีละข้อ หรือทำครบชุดแล้วตรวจคะแนน<br>โจทย์แต่งขึ้นตามขอบเขตอาจารย์ มีทั้งพื้นฐาน การอ่านคำสั่ง และวิเคราะห์ภาพ</p></div></div>${session&&!session.finished?`<div class="note">${icon('info')}<div>คุณมีชุดที่กำลังทำอยู่: ${esc(session.title)}<br><a href="#/quiz">กลับไปทำต่อ ${icon('arrow',14)}</a></div></div>`:''}<div class="mock-banner"><div><h3>ชุดทบทวนรวม 30 ข้อ</h3><p>สุ่มจากคลังทั้ง 8 บท · ตรวจคะแนนเมื่อทำครบ · ไม่จำกัดเวลา</p></div><button class="btn" data-start="mock" data-mode="exam">เริ่มชุดรวม ${icon('arrow',17)}</button></div><div class="quiz-chooser">${chapters.map(c=>{const results=state.history.filter(h=>h.chapter===c.id);const best=results.length?Math.max(...results.map(r=>r.score)):null;return `<section class="quiz-choice"><span class="label">บท ${String(c.id).padStart(2,'0')} · 15 ข้อ</span><h3>${esc(c.shortTitle)}</h3><p>${esc(c.subtitle)}</p><div class="actions"><button class="btn primary small" data-start="${c.id}">ฝึกพร้อมเฉลย</button><button class="btn small" data-start="${c.id}" data-mode="exam">ทำครบแล้วตรวจ</button></div><p class="tiny-note">${best===null?'ยังไม่เคยทำครบชุด':`คะแนนสูงสุด ${best}/15 · ทำครบ ${results.length} ครั้ง`}</p></section>`}).join('')}</div>`;}
 const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]];}return b};
 function startQuiz(target,mode='practice'){let ids,title,chapter=null;if(target==='mock'){ids=shuffle(chapters.flatMap(c=>shuffle(c.questions).slice(0,4).map(q=>q.id))).slice(0,30);title='ชุดทบทวนรวม 30 ข้อ';}else if(target==='wrong'){ids=shuffle(wrongIds().filter(id=>reviewFilter==='all'||qmap[id].chapterId===Number(reviewFilter)));title='ทบทวนข้อที่เคยพลาด';if(!ids.length){toast('ยังไม่มีข้อที่ต้องทบทวน');return}}else{chapter=Number(target);const c=chapters.find(c=>c.id===chapter);if(!c)return;ids=c.questions.map(q=>q.id);title=c.shortTitle;}
 session={ids,title,chapter,mode,index:0,choices:{},checked:{},orders:Object.fromEntries(ids.map(id=>[id,shuffle([0,1,2,3])])),startedAt:Date.now(),finished:false};saveSession();if(location.hash==='#/quiz')render();else location.hash='#/quiz';}
 function record(id,choice){const q=qmap[id];state.answers[id]={choice,correct:choice===q.answer,date:Date.now()};save();}
 function quiz(){if(!session){location.hash='#/practice';return;}if(session.finished){results();return;}sidebar('quiz');breadcrumb('กำลังทำข้อสอบ');const q=qmap[session.ids[session.index]],choice=session.choices[q.id],checked=!!session.checked[q.id],count=Object.keys(session.choices).length,idx=session.index;const order=session.orders[q.id];main.innerHTML=`<div class="quiz-shell"><div class="page-head"><div><h1>${esc(session.title)}</h1><p class="lead">${session.mode==='exam'?'ทำครบแล้วตรวจ · สามารถย้อนกลับไปแก้คำตอบก่อนส่ง':'ฝึกพร้อมเฉลย · เลือกคำตอบแล้วกดตรวจ เพื่ออ่านเหตุผล'}</p></div><a class="btn small" href="#/practice">พักไว้ก่อน</a></div><div class="quiz-meta"><span>ข้อ <strong>${idx+1} / ${session.ids.length}</strong></span><span>ตอบแล้ว ${count} ข้อ</span></div><div class="progress-track"><div class="progress-fill" style="width:${count/session.ids.length*100}%"></div></div><section class="question-panel"><div class="question-top"><span>บท ${q.chapterId} · ${esc(q.chapterTitle)}</span><span class="level">${esc(q.level)}</span></div><h2>${fmt(q.prompt)}</h2>${q.diagram?Diagrams.question(q.diagram):''}<div class="options" role="group" aria-label="ตัวเลือกคำตอบ">${order.map((original,i)=>`<button class="option ${choice===original?'selected':''} ${checked&&original===q.answer?'correct':''} ${checked&&choice===original&&choice!==q.answer?'wrong':''}" data-option="${original}" aria-pressed="${choice===original}" ${checked?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${fmt(q.options[original])}</span></button>`).join('')}</div>${checked?`<div class="feedback ${choice!==q.answer?'wrong':''}" role="status"><strong>${choice===q.answer?'ถูกต้อง เข้าใจหลักการแล้ว':'ยังไม่ถูก ลองดูเหตุผลตรงนี้'}</strong><p>คำตอบที่ถูก: ${fmt(q.options[q.answer])}</p>${fmt(q.explanation)}</div>`:''}<div class="quiz-bottom"><button class="btn" data-prev ${idx===0?'disabled':''}>${icon('left',16)}ข้อก่อนหน้า</button><div class="actions">${session.mode==='practice'&&!checked?`<button class="btn primary" data-check ${choice===undefined?'disabled':''}>ตรวจคำตอบ ${icon('check',16)}</button>`:idx<session.ids.length-1?`<button class="btn primary" data-next>ข้อถัดไป ${icon('arrow',16)}</button>`:`<button class="btn primary" data-finish ${session.mode==='exam'&&count<session.ids.length?'disabled':''}>ตรวจคะแนนทั้งหมด ${icon('check',16)}</button>`}</div></div>${session.mode==='exam'&&idx===session.ids.length-1&&count<session.ids.length?'<p class="tiny-note">ตอบให้ครบทุกข้อก่อนตรวจคะแนน เลือกเลขข้อด้านล่างเพื่อกลับไปทำข้อที่เว้นไว้</p>':''}</section><nav class="question-dots" aria-label="ไปยังข้อสอบ">${session.ids.map((id,i)=>`<button data-jump="${i}" class="${session.choices[id]!==undefined?'answered':''} ${idx===i?'current':''}" aria-label="ไปข้อ ${i+1}${session.choices[id]!==undefined?' ตอบแล้ว':''}" ${idx===i?'aria-current="step"':''}>${i+1}</button>`).join('')}</nav><p class="tiny-note">คำถามและเฉลยสร้างเพื่อฝึกทบทวน ไม่ใช่ข้อสอบจริงของอาจารย์</p></div>`;}
 function finish(){if(!session)return;const unanswered=session.ids.findIndex(id=>session.choices[id]===undefined||(session.mode==='practice'&&!session.checked[id]));if(unanswered!==-1){session.index=unanswered;saveSession();quiz();toast('ยังมีข้อที่ไม่ได้ตอบหรือตรวจคำตอบ');return}session.finished=true;session.ids.forEach(id=>record(id,session.choices[id]));session.score=session.ids.filter(id=>session.choices[id]===qmap[id].answer).length;state.history.push({chapter:session.chapter,title:session.title,score:session.score,total:session.ids.length,date:Date.now()});state.history=state.history.slice(-100);save();saveSession();results();window.scrollTo({top:0});}
 function resultReview(q,choice){const correct=choice===q.answer;return `<details class="review-item"><summary><span class="mark ${correct?'good':''}">${icon(correct?'check':'close',13)}</span><span>${fmt(q.prompt)}</span></summary><div class="review-body">${q.diagram?Diagrams.render(q.diagram):''}<p>คุณตอบ: <strong>${fmt(q.options[choice]??'ไม่ได้ตอบ')}</strong></p><p>คำตอบที่ถูก: <strong>${fmt(q.options[q.answer])}</strong></p><p>${fmt(q.explanation)}</p><a href="#/chapter/${q.chapterId}">กลับไปอ่านบท ${q.chapterId} ${icon('arrow',13)}</a></div></details>`}
 function results(){sidebar('quiz');breadcrumb('ผลการฝึก');const score=session.score,total=session.ids.length,percent=Math.round(score/total*100);main.innerHTML=`<div class="quiz-shell"><section class="result-head"><div class="score-circle"><b>${percent}%</b><span>${score} / ${total} ข้อ</span></div><h1>${percent>=80?'เข้าใจภาพรวมได้ดีแล้ว':percent>=50?'เริ่มเชื่อมโยงได้แล้ว ค่อย ๆ เก็บจุดที่พลาด':'กลับไปอ่านหลักการ แล้วลองใหม่ได้เสมอ'}</h1><p class="lead" style="margin:auto">${esc(session.title)} · คะแนนนี้ใช้ประเมินการฝึก ไม่ใช่การคาดการณ์คะแนนสอบจริง</p><div class="actions"><button class="btn primary" data-retry>ลองทำชุดเดิมอีกครั้ง</button><a class="btn" href="#/review">ทบทวนจุดที่พลาด</a><a class="btn" href="#/practice">เลือกบทอื่น</a></div></section><div class="section-heading"><h2>เฉลยพร้อมเหตุผล</h2><small>กดแต่ละข้อเพื่ออ่าน</small></div>${session.ids.map(id=>resultReview(qmap[id],session.choices[id])).join('')}</div>`;}
 function review(){sidebar('review');breadcrumb('ทบทวนจุดที่พลาด');const ids=wrongIds(),filtered=ids.filter(id=>reviewFilter==='all'||qmap[id].chapterId===Number(reviewFilter));main.innerHTML=`<div class="page-head"><div><h1>กลับมาเก็บจุดที่พลาด</h1><p class="lead">รวมข้อที่คำตอบล่าสุดยังไม่ถูก เมื่อตอบถูกในครั้งถัดไป ข้อนั้นจะออกจากรายการนี้</p></div>${filtered.length?'<button class="btn primary" data-start="wrong">ฝึกข้อเหล่านี้อีกครั้ง</button>':''}</div>${ids.length?`<div class="review-toolbar"><span class="muted">${filtered.length} ข้อที่ต้องทบทวน</span><select id="review-filter" aria-label="กรองข้อที่ผิดตามบท"><option value="all">ทุกบท</option>${chapters.map(c=>`<option value="${c.id}" ${String(c.id)===reviewFilter?'selected':''}>${c.id}. ${esc(c.shortTitle)}</option>`).join('')}</select></div>${filtered.length?filtered.map(id=>resultReview(qmap[id],state.answers[id].choice)).join(''):'<div class="empty-state"><h2>บทนี้ไม่มีข้อที่ค้างทบทวน</h2><p>เลือกบทอื่น หรือกลับไปฝึกชุดใหม่ได้เลย</p></div>'}`:`<div class="empty-state">${icon('check',42)}<h2>${Object.keys(state.answers).length?'ไม่มีข้อผิดที่ค้างทบทวน':'เริ่มฝึก แล้วเราจะช่วยเก็บจุดที่พลาด'}</h2><p>${Object.keys(state.answers).length?'ลองชุดรวมเพื่อเชื่อมความเข้าใจข้ามบท':'ตอบผิดได้เต็มที่ ทุกข้อมีเหตุผลให้เรียนรู้ต่อ'}</p><a class="btn primary" href="#/practice">เลือกข้อสอบฝึก ${icon('arrow',16)}</a></div>`}`;}
 function render(){document.body.classList.remove('menu-open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false');const route=location.hash.replace(/^#\/?/,'').split('?')[0].split('/');if(route[0]==='chapter')lesson(Number(route[1]),location.hash.includes('summary'));else if(route[0]==='chapters')chapterIndex();else if(route[0]==='practice')practice();else if(route[0]==='quiz')quiz();else if(route[0]==='review')review();else dashboard();}
 document.getElementById('menu-toggle').innerHTML=icon('menu');document.getElementById('search-icon').innerHTML=icon('search',16);
 document.getElementById('menu-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open))});document.getElementById('scrim').addEventListener('click',()=>{document.body.classList.remove('menu-open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false')});
 main.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;
 if(b.hasAttribute('data-start')){startQuiz(b.dataset.start,b.dataset.mode||'practice');window.scrollTo({top:0});}
 if(b.hasAttribute('data-scroll')){e.preventDefault();document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth'});}
 if(b.hasAttribute('data-tab')){const id=Number(b.dataset.chapter);location.hash=`#/chapter/${id}${b.dataset.tab==='summary'?'?summary':''}`;}
 if(b.hasAttribute('data-done')){const id=Number(b.dataset.done);if(!state.done.includes(id))state.done.push(id);save();b.classList.remove('primary');b.classList.add('success');b.innerHTML=icon('check',17)+'อ่านบทนี้แล้ว';sidebar('book',id);toast('บันทึกว่าอ่านบทนี้แล้ว');}
 if(b.hasAttribute('data-copy')){const c=chapters.find(c=>c.id===Number(location.hash.split('/')[2]?.split('?')[0]));try{await navigator.clipboard.writeText(c.sections[Number(b.dataset.copy)].code);toast('คัดลอกคำสั่งแล้ว')}catch(err){toast('คัดลอกอัตโนมัติไม่ได้ กรุณาเลือกข้อความในช่องคำสั่ง')}}
 if(b.hasAttribute('data-sim'))Diagrams.update(b.closest('.diagram'),b.dataset.sim);
 if(b.hasAttribute('data-option')){session.choices[session.ids[session.index]]=Number(b.dataset.option);saveSession();const y=window.scrollY;quiz();window.scrollTo({top:y});}
 if(b.hasAttribute('data-check')){const id=session.ids[session.index];if(session.choices[id]!==undefined){session.checked[id]=true;record(id,session.choices[id]);saveSession();const y=window.scrollY;quiz();window.scrollTo({top:y});}}
 if(b.hasAttribute('data-next')){session.index=Math.min(session.ids.length-1,session.index+1);saveSession();quiz();window.scrollTo({top:0});}
 if(b.hasAttribute('data-prev')){session.index=Math.max(0,session.index-1);saveSession();quiz();window.scrollTo({top:0});}
 if(b.hasAttribute('data-jump')){session.index=Number(b.dataset.jump);saveSession();quiz();window.scrollTo({top:0});}
 if(b.hasAttribute('data-finish'))finish();
 if(b.hasAttribute('data-retry')){session={...session,index:0,choices:{},checked:{},orders:Object.fromEntries(session.ids.map(id=>[id,shuffle([0,1,2,3])])),startedAt:Date.now(),finished:false,score:undefined};saveSession();quiz();window.scrollTo({top:0});}
 });
 main.addEventListener('change',e=>{if(e.target.id==='review-filter'){reviewFilter=e.target.value;review()}});
 const search=document.getElementById('search'),searchResults=document.getElementById('search-results');search.addEventListener('input',()=>{const term=search.value.trim().toLowerCase();if(!term){searchResults.hidden=true;return}const found=[];chapters.forEach(c=>{if(`${c.title} ${c.shortTitle} ${c.subtitle}`.toLowerCase().includes(term))found.push({c,title:c.title});c.sections.forEach((s,i)=>{if([s.title,...(s.body||[]),...(s.bullets||[]),s.code||''].join(' ').toLowerCase().includes(term))found.push({c,title:s.title,i})})});searchResults.hidden=false;searchResults.innerHTML=found.length?found.slice(0,10).map(r=>`<a class="search-result" href="#/chapter/${r.c.id}" ${r.i!==undefined?`data-search-section="${r.i}"`:''}>${esc(r.title)}<small>บท ${r.c.id} · ${esc(r.c.shortTitle)}</small></a>`).join(''):'<div class="search-empty">ไม่พบหัวข้อนี้ ลองคำว่า VLAN, Cost หรือ Gateway</div>'});
 searchResults.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;e.preventDefault();const hash=a.getAttribute('href');const section=a.dataset.searchSection;searchResults.hidden=true;search.value='';if(location.hash===hash){render();if(section!==undefined)document.getElementById('section-'+section)?.scrollIntoView();}else{location.hash=hash;if(section!==undefined)requestAnimationFrame(()=>requestAnimationFrame(()=>document.getElementById('section-'+section)?.scrollIntoView()));}});
 document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))searchResults.hidden=true});document.addEventListener('keydown',e=>{if(e.key==='Escape'){searchResults.hidden=true;document.body.classList.remove('menu-open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false')}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();search.focus()}});
 window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0})});render();
})();
